	/**
	 * Default Constructor
	 */
    public MedicationOrderService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new MedicationOrderEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(MedicationOrderRepository.class) );
		this.validator		= applicationContext.getBean(MedicationOrderValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		MedicationOrder
	 */
		public MedicationOrder createMedicationOrder( CreateMedicationOrderCommand command ) {

		MedicationOrder entity = new MedicationOrder();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setMedicationOrderId( command.getMedicationOrderId() );
            entity.setMedicationCode( command.getMedicationCode() );
            entity.setDose( command.getDose() );
            entity.setFrequency( command.getFrequency() );
            entity.setDuration( command.getDuration() );
            entity.setRoute( command.getRoute() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of MedicationOrder {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateMedicationOrderCommand
	 * @return		MedicationOrder
	 */
	public MedicationOrder updateMedicationOrder( UpdateMedicationOrderCommand command ) {

		MedicationOrder entity = new MedicationOrder();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setMedicationOrderId( command.getMedicationOrderId() );
            entity.setMedicationCode( command.getMedicationCode() );
            entity.setDose( command.getDose() );
            entity.setFrequency( command.getFrequency() );
            entity.setDuration( command.getDuration() );
            entity.setOrder( command.getOrder() );
            entity.setPharmacy( command.getPharmacy() );
            entity.setDispenses( command.getDispenses() );
            entity.setRoute( command.getRoute() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of MedicationOrder {0} ", entity.toString() );

		return entity;
	}

